/**
 * Hosted-execution interactive latency: first user-visible outbound and
 * phase timings (send → waitForCompletion → durability drain → post-drain →
 * total).
 *
 * Guest OTel (`agent_sdk.hosted_execution.*`) follows the package's existing
 * guest-side OTel meter conventions (same pattern as `agent_sdk.http.duration`
 * / process-memory histograms) so guest exporters can chart phases without
 * waiting on control-plane scrape.
 *
 * Control-plane scrape of `as_hex` Server-Timing into
 * `agent_sdk.runtime.hosted_execution.*` follows the established
 * `guest_duration_ms` / `guest_network_wait_ms` path so Datadog control-plane
 * dashboards can join execute wall time with guest phases. Both are retained
 * because they feed different scrape surfaces already used in production.
 *
 * Tags stay low-cardinality: channel_kind, phase, outcome, delivery_surface.
 * Never tag message content, Slack IDs, tokens, workflow/request/session IDs.
 */
import { AsyncLocalStorage } from "node:async_hooks";
import { metrics, } from "@opentelemetry/api";
export const HOSTED_EXECUTION_DURATION_METRIC = "agent_sdk.hosted_execution.duration_ms";
export const HOSTED_EXECUTION_VISIBLE_REPLY_METRIC = "agent_sdk.hosted_execution.visible_reply";
/** Server-Timing metric name scraped by the control plane. */
export const HOSTED_EXECUTION_SERVER_TIMING = "as_hex";
const latencyAls = new AsyncLocalStorage();
const INSTRUMENTATION = "agent_sdk";
let meterOverride;
let durationHistogram;
let visibleCounter;
let nowOverride;
/** Monotonic clock used for latency marks (injectable in tests). */
export function hostedExecutionNow() {
    return nowOverride !== undefined ? nowOverride() : performance.now();
}
/** @internal */
export function setHostedExecutionLatencyNowForTests(now) {
    nowOverride = now;
}
/** @internal */
export function setHostedExecutionLatencyMeterForTests(meter) {
    meterOverride = meter;
    durationHistogram = undefined;
    visibleCounter = undefined;
}
/** @internal */
export function resetHostedExecutionLatencyForTests() {
    meterOverride = undefined;
    durationHistogram = undefined;
    visibleCounter = undefined;
    nowOverride = undefined;
}
function resolveMeter() {
    return meterOverride ?? metrics.getMeter(INSTRUMENTATION);
}
function durationInstrument() {
    if (durationHistogram === undefined) {
        durationHistogram = resolveMeter().createHistogram(HOSTED_EXECUTION_DURATION_METRIC, {
            unit: "ms",
            description: "Hosted execution interactive latency phases (first visible, completion, durability, post-drain, total)",
        });
    }
    return durationHistogram;
}
function visibleInstrument() {
    if (visibleCounter === undefined) {
        visibleCounter = resolveMeter().createCounter(HOSTED_EXECUTION_VISIBLE_REPLY_METRIC, {
            description: "Hosted execution first-visible Slack outbound outcome (exact-once per execution)",
        });
    }
    return visibleCounter;
}
export function sanitizeHostedChannelKind(value) {
    const normalized = value
        .trim()
        .toLowerCase()
        .replace(/[^a-z0-9_]+/g, "_")
        .replace(/^_+|_+$/g, "")
        .slice(0, 64);
    return normalized === "" ? "unknown" : normalized;
}
function baseAttrs(store) {
    return {
        channel_kind: store.channelKind,
        delivery_surface: store.deliverySurface,
    };
}
/**
 * Run hosted execution work inside the latency ALS. Slack delivery marks
 * first-visible against this store; no-ops outside the window.
 */
export function runWithHostedExecutionLatency(args, work) {
    const store = {
        startedAt: hostedExecutionNow(),
        channelKind: sanitizeHostedChannelKind(args.channelKind),
        firstVisibleAt: undefined,
        firstVisibleOutcome: undefined,
        deliverySurface: "none",
        visibleCounterEmitted: false,
        errorEmitted: false,
        finalized: false,
    };
    return latencyAls.run(store, work);
}
export function isDuringHostedExecutionLatency() {
    return latencyAls.getStore() !== undefined;
}
/**
 * Mark the first user-visible Slack outbound success. Exact-once: later
 * progress updates and final fallback posts are ignored.
 */
export function markHostedFirstVisibleReply(args) {
    const store = latencyAls.getStore();
    if (store === undefined || store.firstVisibleAt !== undefined) {
        return false;
    }
    store.firstVisibleAt = hostedExecutionNow();
    store.firstVisibleOutcome = args.outcome;
    store.deliverySurface = args.deliverySurface ?? "slack";
    if (!store.visibleCounterEmitted) {
        store.visibleCounterEmitted = true;
        visibleInstrument().add(1, {
            ...baseAttrs(store),
            outcome: args.outcome,
        });
    }
    return true;
}
/**
 * Count a visible-outbound failure when nothing user-visible succeeded yet.
 * Exact-once; ignored after a first-visible mark or a prior error.
 */
export function noteHostedVisibleReplyError(args) {
    const store = latencyAls.getStore();
    if (store === undefined || store.errorEmitted || store.firstVisibleAt !== undefined) {
        return;
    }
    store.errorEmitted = true;
    if (args?.deliverySurface !== undefined) {
        store.deliverySurface = args.deliverySurface;
    }
    else if (store.deliverySurface === "none") {
        store.deliverySurface = "slack";
    }
    if (!store.visibleCounterEmitted) {
        store.visibleCounterEmitted = true;
        visibleInstrument().add(1, {
            ...baseAttrs(store),
            outcome: "error",
        });
    }
}
function resolveOutcome(store) {
    if (store.firstVisibleOutcome !== undefined) {
        return store.firstVisibleOutcome;
    }
    if (store.errorEmitted) {
        return "error";
    }
    return "none";
}
/**
 * Emit phase histograms + optional none counter; return a snapshot for
 * Server-Timing. Safe to call once per ALS window.
 *
 * `endedAt` should be taken as late as possible before the execution reply
 * (or rethrow) is returned so `total` and `post_drain` include eviction and
 * diagnostic write work after durability drain.
 */
export function finalizeHostedExecutionLatency(marks) {
    const store = latencyAls.getStore();
    if (store === undefined || store.finalized) {
        return undefined;
    }
    store.finalized = true;
    const outcome = resolveOutcome(store);
    if (!store.visibleCounterEmitted) {
        store.visibleCounterEmitted = true;
        visibleInstrument().add(1, {
            ...baseAttrs(store),
            outcome: "none",
        });
    }
    const phases = {
        durability_drain: Math.max(0, marks.drainAt - marks.completionAt),
        post_drain: Math.max(0, marks.endedAt - marks.drainAt),
        total: Math.max(0, marks.endedAt - store.startedAt),
    };
    if (store.firstVisibleAt !== undefined) {
        phases.to_first_visible = Math.max(0, store.firstVisibleAt - store.startedAt);
        phases.first_visible_to_completion = Math.max(0, marks.completionAt - store.firstVisibleAt);
    }
    const attrs = {
        channel_kind: store.channelKind,
        outcome,
        delivery_surface: store.deliverySurface,
    };
    const histogram = durationInstrument();
    const phaseNames = [
        "to_first_visible",
        "first_visible_to_completion",
        "durability_drain",
        "post_drain",
        "total",
    ];
    for (const phase of phaseNames) {
        const value = phases[phase];
        if (value === undefined) {
            continue;
        }
        histogram.record(value, { ...attrs, phase });
    }
    return {
        channelKind: store.channelKind,
        outcome,
        deliverySurface: store.deliverySurface,
        phases,
    };
}
export function formatHostedExecutionLatencyServerTiming(snapshot) {
    const parts = [];
    const order = [
        "to_first_visible",
        "first_visible_to_completion",
        "durability_drain",
        "post_drain",
        "total",
    ];
    for (const phase of order) {
        const dur = snapshot.phases[phase];
        if (dur === undefined) {
            continue;
        }
        parts.push(`${HOSTED_EXECUTION_SERVER_TIMING};desc="${phase}";dur=${Math.max(0, dur).toFixed(1)};outcome="${snapshot.outcome}";ch="${snapshot.channelKind}";sf="${snapshot.deliverySurface}"`);
    }
    return parts;
}
